examples:
$changeDefinitionDetail = @{
    operations = @(
        @{
            httpMethod = "DELETE"
            uri = "https://management.azure.com/subscriptions/$((Get-AzContext).Subscription.Id)/resourceGroups/rg-test/providers/Microsoft.Storage/storageAccounts/teststorageaccount?api-version=2023-01-01"
        }
    )
}

New-AzChangeSafetyChangeRecord -Name "storageDelete" `
    -ResourceGroupName "rg-changeops" `
    -ChangeType "ManualTouch" `
    -RolloutType "Normal" `
    -ChangeDefinitionKind "ApiOperations" `
    -ChangeDefinitionName "Delete storage account" `
    -ChangeDefinitionDetail $changeDefinitionDetail

New-AzChangeSafetyStageMap -Name "regional-rollout" `
    -ResourceGroupName "rg-changeops" `
    -Stage @(
        @{ 
            name = "eastus-canary"
            sequence = 1
            stageVariables = @{
                region = "eastus"
                replicas = 1
                enableMonitoring = $true
            }
        },
        @{ 
            name = "eastus-prod"
            sequence = 2
            stageVariables = @{
                region = "eastus"
                replicas = 3
                enableMonitoring = $true
            }
        },
        @{ 
            name = "westus-prod"
            sequence = 3
            stageVariables = @{
                region = "westus"
                replicas = 3
                enableMonitoring = $true
            }
        }
    )

Update-AzChangeSafetyStageMap -Name "regional-rollout" `
    -ResourceGroupName "rg-changeops" `
    -Stage @(
        @{ 
            name = "eastus-canary"
            sequence = 1
            stageVariables = @{
                region = "eastus"
                replicas = 2
                enableMonitoring = $true
                timeout = 3600
            }
        }
    )
